export default App;

import React, { useState, useRef, useEffect } from 'react';
import { GoogleGenAI, Chat, GenerateContentResponse } from "@google/genai";
import { MessageSquare, X, Send, Bot, User, Loader2, Sparkles, ChevronRight } from 'lucide-react';
import { PACKAGES } from '../constants';

interface Message {
  role: 'user' | 'model';
  text: string;
}

const HealthAssistant: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<Message[]>([
    { role: 'model', text: "Namaste! I'm your AI Health Concierge from National Diagnostic Center. I can help you find health packages, understand test prep, or check test timings. How can I assist you today?" }
  ]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const chatSession = useRef<Chat | null>(null);

  const quickPrompts = [
    "What's in the Essential Health Check?",
    "Fasting for Thyroid test?",
    "Do you offer Home Collection?",
    "How to get digital reports?"
  ];

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, isOpen]);

  const initializeChat = async () => {
    try {
      if (!process.env.API_KEY) return;

      const packageDescriptions = PACKAGES.map(p => 
        `- ${p.title} (₹${p.price}): Includes ${p.features.join(', ')}. Recommended for ${p.recommendedFor}.`
      ).join('\n');

      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      chatSession.current = ai.chats.create({
        model: 'gemini-3-flash-preview',
        config: {
          systemInstruction: `You are 'Naya', the professional and empathetic AI Assistant for 'National Diagnostic Center' in Lucknow.

          **Tone:** Professional, clear, warm, and distinctly healthcare-focused. Use "We" and "Our" when referring to the lab.

          **Knowledge Base:**
          - Address: Tedi Pulia, Ring Road, Lucknow.
          - Services: Home Collection (Free > ₹500), NABL Standards, Digital Reports in 6-24h.
          - Packages: ${packageDescriptions}
          - Prep: Fasting (10-12h) needed for Lipid, Thyroid, Sugar. No prep for CBC.

          **Strict Guidelines:**
          1. NEVER provide a diagnosis.
          2. ALWAYS advise consulting a physician for test result interpretation.
          3. If symptoms are mentioned, suggest the relevant screening package but mandate a doctor's visit.
          4. Keep responses concise and use bullet points for clarity.
          `,
        },
      });
    } catch (error) {
      console.error("Failed to init chat", error);
    }
  };

  useEffect(() => {
    if (isOpen && !chatSession.current) {
      initializeChat();
    }
  }, [isOpen]);

  const handleSend = async (userMsg: string) => {
    if (!userMsg.trim() || isLoading) return;

    setMessages(prev => [...prev, { role: 'user', text: userMsg }]);
    if (input) setInput('');
    setIsLoading(true);

    try {
      if (!chatSession.current) await initializeChat();

      if (chatSession.current) {
        const result = await chatSession.current.sendMessageStream({ message: userMsg });
        let fullResponse = "";
        setMessages(prev => [...prev, { role: 'model', text: "" }]);

        for await (const chunk of result) {
          const c = chunk as GenerateContentResponse;
          if (c.text) {
            fullResponse += c.text;
            setMessages(prev => {
              const newHistory = [...prev];
              newHistory[newHistory.length - 1].text = fullResponse;
              return newHistory;
            });
          }
        }
      }
    } catch (error) {
      setMessages(prev => [...prev, { role: 'model', text: "I apologize, but I'm having trouble connecting right now. Please call us at +91 75059 32068 for immediate assistance." }]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <>
      <button
        onClick={() => setIsOpen(!isOpen)}
        className={`fixed bottom-6 right-6 z-50 p-4 rounded-2xl shadow-2xl transition-all duration-300 ${
          isOpen ? 'bg-navy rotate-90 scale-90' : 'bg-primary hover:bg-primary-dark hover:scale-110'
        } text-white flex items-center justify-center`}
        aria-label="Health Assistant"
      >
        {isOpen ? <X size={24} /> : <MessageSquare size={24} />}
      </button>

      {isOpen && (
        <div className="fixed bottom-24 right-6 z-50 w-[95vw] sm:w-[400px] h-[600px] bg-white rounded-[2rem] shadow-2xl border border-slate-100 flex flex-col overflow-hidden animate-slide-up">

          {/* Header */}
          <div className="bg-navy p-5 flex items-center gap-4">
            <div className="w-12 h-12 bg-primary/20 rounded-2xl flex items-center justify-center border border-primary/30">
              <Sparkles size={24} className="text-primary" />
            </div>
            <div>
              <h3 className="font-bold text-white text-base">Health Assistant</h3>
              <p className="text-xs text-slate-400 flex items-center gap-1.5">
                <span className="w-2 h-2 rounded-full bg-secondary animate-pulse"></span>
                Naya is online to help
              </p>
            </div>
          </div>

          {/* Messages Area */}
          <div className="flex-grow overflow-y-auto p-5 space-y-6 bg-slate-50/50">
            {messages.map((msg, idx) => (
              <div
                key={idx}
                className={`flex items-start gap-3 ${msg.role === 'user' ? 'flex-row-reverse' : 'flex-row'}`}
              >
                <div className={`w-9 h-9 rounded-xl flex items-center justify-center shrink-0 ${
                  msg.role === 'user' ? 'bg-primary text-white shadow-lg shadow-primary/20' : 'bg-white border border-slate-200 text-primary'
                }`}>
                  {msg.role === 'user' ? <User size={18} /> : <Bot size={18} />}
                </div>
                <div className={`p-4 rounded-2xl max-w-[85%] text-sm leading-relaxed shadow-sm ${
                  msg.role === 'user' ? 'bg-primary text-white rounded-tr-none' : 'bg-white text-slate-700 border border-slate-100 rounded-tl-none'
                }`}>
                  {msg.text}
                </div>
              </div>
            ))}
            {isLoading && (
              <div className="flex items-center gap-2 text-slate-400 text-xs ml-12 italic">
                <Loader2 size={14} className="animate-spin" />
                <span>Naya is typing...</span>
              </div>
            )}
            <div ref={messagesEndRef} />
          </div>

          {/* Input & Footer */}
          <div className="p-4 bg-white border-t border-slate-100">
            {messages.length < 3 && !isLoading && (
              <div className="flex flex-wrap gap-2 mb-4">
                {quickPrompts.map((p, i) => (
                  <button
                    key={i}
                    onClick={() => handleSend(p)}
                    className="text-[11px] font-bold text-slate-500 bg-slate-50 hover:bg-slate-100 border border-slate-200 px-3 py-1.5 rounded-full transition-all flex items-center gap-1"
                  >
                    {p} <ChevronRight size={10} />
                  </button>
                ))}
              </div>
            )}

            <form onSubmit={(e) => { e.preventDefault(); handleSend(input); }} className="relative flex items-center">
              <input
                type="text"
                value={input}
                onChange={(e) => setInput(e.target.value)}
                placeholder="Ask Naya about health tests..."
                className="w-full pl-4 pr-12 py-3.5 bg-slate-50 border border-slate-200 rounded-2xl text-sm focus:outline-none focus:ring-4 focus:ring-primary/10 focus:bg-white transition-all"
              />
              <button
                type="submit"
                disabled={isLoading || !input.trim()}
                className="absolute right-2 p-2.5 bg-primary text-white rounded-xl hover:bg-primary-dark disabled:opacity-50 transition-colors"
              >
                <Send size={18} />
              </button>
            </form>
            <p className="text-[10px] text-center text-slate-400 mt-3 font-medium">
              Information for guidance only. Not a medical diagnosis.
            </p>
          </div>
        </div>
      )}
    </>
  );
};

export default HealthAssistant;

