                    <Link
                      key={link.name}
                      to={link.path}
                      onClick={() => setIsOpen(false)}
                      className={`flex items-center justify-between px-4 py-3.5 rounded-xl transition-all ${
                        active 
                          ? 'bg-primary/10 text-primary font-semibold' 
                          : 'text-slate-700 font-medium hover:bg-slate-50'
                      }`}
