      initializeChat();
    }
  }, [isOpen]);

  const handleSend = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!input.trim() || isLoading) return;

    const userMsg = input.trim();
    setMessages(prev => [...prev, { role: 'user', text: userMsg }]);
    setInput('');
    setIsLoading(true);

    try {
      if (!chatSession.current) await initializeChat();

      if (chatSession.current) {
        const result = await chatSession.current.sendMessageStream({ message: userMsg });
        let fullResponse = "";
        setMessages(prev => [...prev, { role: 'model', text: "" }]);

        for await (const chunk of result) {
          const c = chunk as GenerateContentResponse;
          if (c.text) {
            fullResponse += c.text;
            setMessages(prev => {
              const newHistory = [...prev];
              newHistory[newHistory.length - 1].text = fullResponse;
              return newHistory;
            });
          }
        }
      }
    } catch (error) {
      setMessages(prev => [...prev, { role: 'model', text: "I apologize, but I'm having trouble connecting right now." }]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <>
      <button
        onClick={() => setIsOpen(!isOpen)}
        className={`fixed bottom-6 right-6 z-50 p-4 rounded-full shadow-2xl transition-all duration-300 ${
          isOpen ? 'bg-slate-800 rotate-90' : 'bg-primary hover:bg-sky-600 hover:scale-110'
        } text-white flex items-center justify-center`}
      >
        {isOpen ? <X size={24} /> : <MessageSquare size={24} />}
      </button>

      {isOpen && (
        <div className="fixed bottom-24 right-6 z-50 w-[90vw] sm:w-[380px] h-[500px] bg-white rounded-2xl shadow-2xl border border-slate-200 flex flex-col overflow-hidden">
          <div className="bg-slate-900 p-4 flex items-center gap-3 border-b border-slate-800">
            <div className="w-10 h-10 bg-primary/20 rounded-full flex items-center justify-center border border-primary/50">
              <Sparkles size={20} className="text-primary" />
            </div>
            <div>
              <h3 className="font-bold text-white text-sm">AI Health Assistant</h3>
              <p className="text-xs text-slate-400 flex items-center gap-1">
                <span className="w-1.5 h-1.5 rounded-full bg-green-500 animate-pulse"></span>
                Online
              </p>
            </div>
          </div>
          <div className="flex-grow overflow-y-auto p-4 space-y-4 bg-slate-50">
            {messages.map((msg, idx) => (
              <div key={idx} className={`flex items-start gap-2.5 ${msg.role === 'user' ? 'flex-row-reverse' : 'flex-row'}`}>
                <div className={`w-8 h-8 rounded-full flex items-center justify-center shrink-0 ${msg.role === 'user' ? 'bg-indigo-100 text-indigo-600' : 'bg-white border border-slate-200 text-primary'}`}>
                  {msg.role === 'user' ? <User size={16} /> : <Bot size={16} />}
                </div>
                <div className={`p-3 rounded-2xl max-w-[80%] text-sm leading-relaxed shadow-sm ${msg.role === 'user' ? 'bg-indigo-600 text-white rounded-tr-none' : 'bg-white text-slate-700 border border-slate-100 rounded-tl-none'}`}>
                  {msg.text}
                </div>
              </div>
            ))}
            {isLoading && (
              <div className="flex items-center gap-2 text-slate-400 text-xs ml-10">
                <Loader2 size={12} className="animate-spin" />
                <span>Thinking...</span>
              </div>
            )}
            <div ref={messagesEndRef} />
          </div>
          <form onSubmit={handleSend} className="p-3 bg-white border-t border-slate-100">
            <div className="relative flex items-center">
              <input
                type="text"
                value={input}
                onChange={(e) => setInput(e.target.value)}
                placeholder="Ask about tests, fasting..."
                className="w-full pl-4 pr-12 py-3 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none"
              />
              <button type="submit" disabled={isLoading || !input.trim()} className="absolute right-2 p-2 bg-primary text-white rounded-lg">
                <Send size={16} />
              </button>
            </div>
          </form>
        </div>
      )}
    </>
  );
};

export default HealthAssistant;

import React, { useState } from 'react';
import { CheckCircle2, Clock, FileText, ChevronDown, ChevronUp } from 'lucide-react';
import { TestPackage } from '../types';
import Button from './Button';
import { useBooking } from '../contexts/BookingContext';

interface PackageCardProps {
  pkg: TestPackage;
}

const PackageCard: React.FC<PackageCardProps> = ({ pkg }) => {
  const { openBooking } = useBooking();
  const [isExpanded, setIsExpanded] = useState(false);

  const discount = Math.round(((pkg.originalPrice - pkg.price) / pkg.originalPrice) * 100);
  const INITIAL_DISPLAY_COUNT = 3;
  const hasMore = pkg.features.length > INITIAL_DISPLAY_COUNT;
  const displayedFeatures = isExpanded ? pkg.features : pkg.features.slice(0, INITIAL_DISPLAY_COUNT);

  return (
    <div className="bg-white rounded-2xl shadow-lg hover:shadow-xl transition-shadow duration-300 border border-slate-100 flex flex-col h-full overflow-hidden relative group">
      {pkg.isPopular && (
        <div className="absolute top-4 right-4 bg-orange-100 text-orange-600 px-3 py-1 rounded-full text-[10px] sm:text-xs font-bold uppercase tracking-wide">
          Most Popular
        </div>
      )}

      <div className="p-4 sm:p-6 pb-2">
        <span className="inline-block px-3 py-1 rounded-full bg-primary/10 text-primary text-[10px] sm:text-xs font-semibold mb-3">
          {pkg.category}
        </span>
        <h3 className="text-lg sm:text-xl font-bold text-slate-900 mb-2">{pkg.title}</h3>
        <p className="text-slate-500 text-xs sm:text-sm mb-4">Recommended for: {pkg.recommendedFor}</p>

        <div className="flex items-baseline gap-2 mb-6">
          <span className="text-2xl sm:text-3xl font-bold text-slate-900">₹{pkg.price}</span>
          <span className="text-xs sm:text-sm text-slate-400 line-through">₹{pkg.originalPrice}</span>
          <span className="text-xs sm:text-sm font-semibold text-green-600 ml-2">{discount}% OFF</span>
        </div>
      </div>

      {/* Divider */}
      <div className="h-px bg-slate-100 mx-4 sm:mx-6"></div>

      <div className="p-4 sm:p-6 pt-4 flex-grow flex flex-col">
        <div className="flex items-center gap-2 mb-4 text-sm font-medium text-slate-700">
           <FileText size={16} className="text-secondary" />
           <span>Includes {pkg.parameters} Parameters</span>
        </div>

        <ul className="space-y-2 sm:space-y-3 mb-4">
          {displayedFeatures.map((feature, idx) => (
            <li key={idx} className="flex items-start gap-2 text-xs sm:text-sm text-slate-600">
              <CheckCircle2 size={16} className="text-secondary shrink-0 mt-0.5" />
              <span>{feature}</span>
            </li>
          ))}
        </ul>

        {hasMore && (
           <button 
             onClick={() => setIsExpanded(!isExpanded)}
             className="text-xs font-semibold text-primary hover:text-sky-700 transition-colors flex items-center gap-1 mb-4 focus:outline-none w-fit"
           >
             {isExpanded ? (
               <>Read Less <ChevronUp size={14} /></>
             ) : (
               <>Read More (+{pkg.features.length - INITIAL_DISPLAY_COUNT} tests) <ChevronDown size={14} /></>
             )}
           </button>
        )}

        <div className="flex items-center gap-2 text-[10px] sm:text-xs text-slate-400 mb-6 mt-auto">
           <Clock size={14} />
           <span>Report within 24 hours</span>
        </div>
      </div>

      <div className="p-4 sm:p-6 pt-0 mt-auto">
        <Button 
           variant="whatsapp" 
           fullWidth 
           onClick={() => openBooking(pkg.title)}
           className="text-sm sm:text-base py-2.5 sm:py-3"
        >
          Book Now
        </Button>
      </div>
    </div>
  );
};

